                v_cpu_count_min=2,
                v_cpu_count_max=8,
                memory_min=Size.gibibytes(4),
                memory_max=Size.gibibytes(32),
        
                # CPU preferences
                cpu_manufacturers=[ec2.CpuManufacturer.INTEL, ec2.CpuManufacturer.AMD],
                instance_generations=[ec2.InstanceGeneration.CURRENT],
        
