    AMD = "AMD"
    '''AMD CPUs (e.g., EPYC families).'''
    AWS = "AWS"
    '''AWS-designed CPUs (e.g., Graviton families).'''
    APPLE = "APPLE"
    '''Apple CPUs (e.g., M1, M2).'''


